export const ALL_INDONESIA_REGENCIES: WilayahRegency[] = Object.values(INDONESIA_REGENCIES_BY_PROVINCE).flat();

/**
 * Mendapatkan daftar semua provinsi di Indonesia (38 Provinsi)
 */
export function getProvinces(): WilayahProvince[] {
  return INDONESIA_PROVINCES;
}

/**
 * Mencari provinsi berdasarkan nama atau kode (case-insensitive & fuzzy)
 */
export function findProvince(query: string): WilayahProvince | undefined {
  if (!query) return undefined;
  const q = query.trim().toLowerCase();
  return INDONESIA_PROVINCES.find(
    (p) =>
      p.kode === q ||
      p.nama.toLowerCase() === q ||
      p.ibukota.toLowerCase() === q ||
      p.nama.toLowerCase().includes(q) ||
      q.includes(p.nama.toLowerCase()) ||
      (q.includes("jakarta") && p.kode === "31") ||
      (q.includes("dki") && p.kode === "31") ||
      (q.includes("yogyakarta") && p.kode === "34") ||
      (q.includes("diy") && p.kode === "34") ||
      (q.includes("jabar") && p.kode === "32") ||
      (q.includes("jateng") && p.kode === "33") ||
      (q.includes("jatim") && p.kode === "35") ||
      (q.includes("banten") && p.kode === "36") ||
      (q.includes("sumut") && p.kode === "12") ||
      (q.includes("sumbar") && p.kode === "13") ||
      (q.includes("sumsel") && p.kode === "16") ||
      (q.includes("sulsel") && p.kode === "73") ||
      (q.includes("sulut") && p.kode === "71") ||
      (q.includes("sultra") && p.kode === "74") ||
      (q.includes("kaltim") && p.kode === "64") ||
      (q.includes("kalbar") && p.kode === "61") ||
      (q.includes("kalsel") && p.kode === "63") ||
      (q.includes("kalteng") && p.kode === "62") ||
      (q.includes("kaltara") && p.kode === "65") ||
      (q.includes("babel") && p.kode === "19") ||
      (q.includes("kepri") && p.kode === "21") ||
      (q.includes("ntb") && p.kode === "52") ||
      (q.includes("ntt") && p.kode === "53")
  );
}

/**
 * Mendapatkan daftar kabupaten/kota berdasarkan kode atau nama provinsi
 */
export function getRegenciesByProvince(provinceQuery?: string | null): WilayahRegency[] {
  if (!provinceQuery) return ALL_INDONESIA_REGENCIES;
  const prov = findProvince(provinceQuery);
  if (!prov) return [];
  return INDONESIA_REGENCIES_BY_PROVINCE[prov.kode] || [];
}

/**
 * Mencari kabupaten/kota berdasarkan nama atau kode pos di seluruh Indonesia
 */
export function searchRegencies(query: string, provinceQuery?: string | null): WilayahRegency[] {
  const pool = provinceQuery ? getRegenciesByProvince(provinceQuery) : ALL_INDONESIA_REGENCIES;
  if (!query || !query.trim()) return pool;
  const q = query.trim().toLowerCase();
  return pool.filter(
    (r) =>
      r.nama.toLowerCase().includes(q) ||
      r.ibukota.toLowerCase().includes(q) ||
      r.kode.toLowerCase().includes(q) ||
      r.kodepos.includes(q) ||
      r.kodeposList.some((kp) => kp.includes(q))
  );
}

/**
 * Mencari kabupaten/kota dan provinsi berdasarkan kode pos
 */
export function findWilayahByPostalCode(postalCode: string): {
  province: WilayahProvince | undefined;
  regency: WilayahRegency | undefined;
} {
  if (!postalCode) return { province: undefined, regency: undefined };
  const cleanCode = postalCode.trim();
  const regency = ALL_INDONESIA_REGENCIES.find(
    (r) => r.kodepos === cleanCode || r.kodeposList.includes(cleanCode)
  );
  if (!regency) return { province: undefined, regency: undefined };
  const province = INDONESIA_PROVINCES.find((p) => p.kode === regency.provinceCode);
  return { province, regency };
}

/**
 * Fetch data provinsi dari database backend REST API
 */
export async function fetchProvincesFromApi(search?: string): Promise<WilayahProvince[]> {
  try {
    const query = search ? `?search=${encodeURIComponent(search)}` : "";
    const res = await fetch(`/api/v1/public/wilayah/provinces${query}`);
    if (!res.ok) throw new Error("Gagal mengambil data provinsi dari database");
    const json = await res.json();
    return json.data || INDONESIA_PROVINCES;
  } catch {
    return search
      ? getProvinces().filter((p) =>
          p.nama.toLowerCase().includes(search.toLowerCase()),
        )
      : getProvinces();
  }
}

/**
 * Fetch data kabupaten/kota dari database backend REST API
 */
export async function fetchRegenciesFromApi(
  province?: string,
  search?: string,
): Promise<WilayahRegency[]> {
  try {
    const params = new URLSearchParams();
    if (province) params.set("province", province);
    if (search) params.set("search", search);
    const query = params.toString() ? `?${params.toString()}` : "";
    const res = await fetch(`/api/v1/public/wilayah/regencies${query}`);
    if (!res.ok) throw new Error("Gagal mengambil data kabupaten/kota dari database");
    const json = await res.json();
    return json.data || getRegenciesByProvince(province);
  } catch {
    return searchRegencies(search || "", province);
  }
}

export interface WilayahDistrict {
  kode: string;
  regencyKode: string;
  provinceKode: string;
  nama: string;
}

export interface WilayahVillage {
  kode: string;
  districtKode: string;
  regencyKode: string;
  provinceKode: string;
  nama: string;
  kodepos: string;
}

/**
 * Fetch data kecamatan dari database backend REST API
 */
export async function fetchDistrictsFromApi(
  regency?: string,
  province?: string,
  search?: string,
): Promise<WilayahDistrict[]> {
  try {
    const params = new URLSearchParams();
    if (regency) params.set("regency", regency);
    if (province) params.set("province", province);
    if (search) params.set("search", search);
    const query = params.toString() ? `?${params.toString()}` : "";
    const res = await fetch(`/api/v1/public/wilayah/districts${query}`);
    if (!res.ok) throw new Error("Gagal mengambil data kecamatan dari database");
    const json = await res.json();
    return json.data || [];
  } catch {
    return [];
  }
}

/**
 * Fetch data kelurahan/desa dari database backend REST API
 */
export async function fetchVillagesFromApi(
  district?: string,
  regency?: string,
  search?: string,
  kodepos?: string,
): Promise<WilayahVillage[]> {
  try {
    const params = new URLSearchParams();
    if (district) params.set("district", district);
    if (regency) params.set("regency", regency);
    if (search) params.set("search", search);
    if (kodepos) params.set("kodepos", kodepos);
    const query = params.toString() ? `?${params.toString()}` : "";
    const res = await fetch(`/api/v1/public/wilayah/villages${query}`);
    if (!res.ok) throw new Error("Gagal mengambil data kelurahan/desa dari database");
    const json = await res.json();
    return json.data || [];
  } catch {
    return [];
  }
}
